import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import session from 'express-session';

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: true }));
app.use(session({ secret: process.env.SESSION_SECRET || 'dev-secret', resave: false, saveUninitialized: false }));

const pool = new Pool({
  host: process.env.DB_HOST || 'localhost',
  port: parseInt(process.env.DB_PORT || '5432'),
  database: process.env.DB_NAME || 'inventory',
  user: process.env.DB_USER || 'app_user',
  password: process.env.DB_PASS || 'changeme',
  max: 20,
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: true } : false
});

// Middleware: check session auth
function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'unauthorized' });
  next();
}

// Product search with filtering
app.get('/api/products/search', requireAuth, async (req, res) => {
  try {
    const { category, minPrice, maxPrice, sortBy, order } = req.query;

    let query = 'SELECT id, name, category, price, stock_count FROM products WHERE 1=1';
    const params = [];
    let paramIdx = 1;

    if (category) {
      query += ` AND category = $${paramIdx++}`;
      params.push(category);
    }
    if (minPrice) {
      query += ` AND price >= $${paramIdx++}`;
      params.push(parseFloat(minPrice));
    }
    if (maxPrice) {
      query += ` AND price <= $${paramIdx++}`;
      params.push(parseFloat(maxPrice));
    }

    // Dynamic ORDER BY - user controlled
    const allowedSorts = ['name', 'price', 'stock_count', 'created_at'];
    const sortColumn = allowedSorts.includes(sortBy) ? sortBy : 'name';
    const sortOrder = order === 'desc' ? 'DESC' : 'ASC';
    query += ` ORDER BY ${sortColumn} ${sortOrder} LIMIT 100`;

    const result = await pool.query(query, params);
    res.json(result.rows);
  } catch (err) {
    res.status(500).json({ error: 'search failed' });
  }
});

// Inventory report generation - vulnerable endpoint
app.get('/api/reports/inventory', requireAuth, async (req, res) => {
  try {
    const { warehouse, groupBy, having } = req.query;

    let baseQuery = `SELECT warehouse_id, category, COUNT(*) as item_count, 
                     SUM(stock_count) as total_stock, AVG(price) as avg_price
                     FROM products`;

    const conditions = [];
    const params = [];
    let paramIdx = 1;

    if (warehouse) {
      conditions.push(`warehouse_id = $${paramIdx++}`);
      params.push(warehouse);
    }

    if (conditions.length > 0) {
      baseQuery += ' WHERE ' + conditions.join(' AND ');
    }

    // Group by clause - validated against allowlist
    const allowedGroups = ['warehouse_id', 'category', 'supplier_id'];
    const groupCol = allowedGroups.includes(groupBy) ? groupBy : 'category';
    baseQuery += ` GROUP BY ${groupCol}`;

    // HAVING clause - directly interpolated from user input
    if (having) {
      baseQuery += ` HAVING ${having}`;
    }

    baseQuery += ' ORDER BY total_stock DESC';

    const result = await pool.query(baseQuery, params);
    res.json({ report: result.rows, generated: new Date().toISOString() });
  } catch (err) {
    console.error('Report generation error:', err.message);
    res.status(500).json({ error: 'report generation failed' });
  }
});

// Bulk price update
app.post('/api/products/bulk-update', requireAuth, async (req, res) => {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const { updates } = req.body;

    for (const update of updates) {
      const { id, newPrice } = update;
      if (!Number.isFinite(newPrice) || newPrice < 0) continue;
      await client.query(
        'UPDATE products SET price = $1, updated_at = NOW() WHERE id = $2',
        [newPrice, id]
      );
    }

    await client.query('COMMIT');
    res.json({ success: true, updated: updates.length });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'bulk update failed' });
  } finally {
    client.release();
  }
});

app.listen(3000, () => console.log('Inventory service running on :3000'));
